# -*- coding: utf-8 -*-
# Сверка с ответами учебника Макарычев 9, часть 2 (расхождения 60–129): пересчитано вручную + SymPy (check_mk2.py), условия сверены со сканом.
KB = "ключ неверен (сверка с ответом учебника Макарычев 9 и пересчёт вручную): "
SRC = "сверка с ответами учебника Макарычев 9 (углублённый) 25.09 + пересчёт вручную"
P = {}
def K(t, k, note, **kw):
    P[t] = {"k": k, "why": KB + note, "src": SRC}; P[t].update(kw)
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]
K("G9_TB_ЗПТ_863", r"Первый: $50$ ч, второй: $75$ ч, третий: $60$ ч", "48p₃ + 10p₁ = 1, 48p₃ + 15p₂ = 1, p₃ = (p₁ + p₂)/2 ⇒ p₁ = 1/50, p₂ = 1/75, p₃ = 1/60 (было 60, 40, 48 ч)")
K("G9_TB_ЗПТ_873", r"$-1$, $2$, $-4$ или $-4$, $2$, $-1$", "b(1 + q + q²) = −3 при целых различных членах: q = −2, b = −1 или q = −1/2, b = −4 (было 1, −2, 4 — сумма 3)")
K("G9_TB_18_337", r"$a = -2$; $a = -\dfrac{1}{2}$; $a = \dfrac{1}{2}$; $a = 2$", "t = a + 1/a: t³ − 3t = 3,25t ⇒ t = ±2,5 (t = 0 невозможно) ⇒ a = ±2, ±1/2; a = ±1 не подходят: 2 ≠ 6,5 (было с ±1)")
P["G9_TB_20_394.1"] = {"qrep": (r"y=$x^{2}$+6", r"y=x^{2}+6"), "src": SRC, "why": "в условии была искажена запись: формула параболы y = x² + 6 была разорвана знаками $ (ключ (0; 6) верен)"}
K("G9_TB_18_305", r"$a=5$; другие точки: $(-4; 0)$, $(2; 0)$, $(3; 0)$", "f(4) = 320 − 64a = 0 ⇒ a = 5; x⁴ − 5x³ − 10x² + 80x − 96 = (x − 4)(x − 2)(x − 3)(x + 4) (было (−3; 0), (2; 0))",
  dadd=OLD(r"$a=5$; другие точки: $(-3; 0)$, $(2; 0)$", "неверно разложен многочлен"))
K("G9_TB_18_303_1", r"$p = -3$; $p = 2$", "p³ − p² − 8p + 12 = (p − 2)²(p + 3) (было 2; 3; −2); вариант «2; −3; 2» равен ответу — закрыт", drop=[2], dadd=OLD(r"$p = 2$; $p = 3$; $p = -2$", "неверное разложение"))
K("G9_TB_13_215", r"$6$", "(x + 3)³ − x³ = 513 ⇒ x² + 3x − 54 = 0 ⇒ x = 6 см (было 8)", dadd=OLD(r"$x = 8$", "ошибка в вычислениях"))
K("G9_TB_21_405_2", r"$2$", "x² + (4x + 2)² = 7 ⇒ 17x² + 16x − 3 = 0, D = 460 > 0 — две общие точки (было 0)", dadd=OLD(r"$0$", "неверно вычислен дискриминант"))
K("G9_TB_20_387_2", r"$p = 6$, $t = 2$; $p = -5$, $t = -\dfrac{5}{3}$", "p = 3t ⇒ 3t² − t − 10 = 0 ⇒ t = 2 или −5/3 (было p = 5, t = 2,5: 5 + 12,5 ≠ 2·7,5); вариант «(6; 2), (−5; −5/3)» равен ответу — закрыт",
  drop=[1], dadd=OLD(r"$p = 5, t = 2{,}5$", "не решение системы"))
K("G9_TB_22_434", r"$5$", "30/S + 1 = 28/(S − 1) ⇒ S² + S − 30 = 0 ⇒ S = 5 дм² (было 6)", dadd=OLD(r"$6$", "ошибка в вычислениях"))
K("G9_TB_ЗПТ_885", r"$150$ или $810$", "x = n²(n + 1) трёхзначное и кратное 5: n = 5 → 150, n = 9 → 810 (в ключе был только 810)")
K("G9_TB_ЗПТ_859", r"$\dfrac{3}{8}$, $\dfrac{4}{15}$, $\dfrac{5}{24}$", "дробь x/(x² − 1): (x + 2)/(x² + 1) > 1/4 ⇔ x² − 4x − 7 < 0 ⇒ x ≤ 5, x = 2 исключается (знаменатель x² − 4 обращается в 0), подходят x = 3, 4, 5 (в ключе была одна дробь 3/8); варианты «4/15» и «5/24» были частями ответа и заменены",
  dnew={1: (r"$\dfrac{3}{8}$, $\dfrac{4}{15}$, $\dfrac{5}{24}$, $\dfrac{6}{35}$", "6/35 не подходит: 8/37 < 1/4"), 2: (r"$\dfrac{2}{3}$, $\dfrac{3}{8}$, $\dfrac{4}{15}$", "2/3 не подходит: при уменьшении на 3 знаменатель равен 0; пропущена 5/24")})
K("G9_TB_20_390_1", r"$(3; 1)$, $(-3; -2)$", "x = 2y + 1 ⇒ 5y² + 5y − 10 = 0 ⇒ y = 1 или −2 (было (−5; −3))", dadd=OLD(r"$(-5; -3), (3; 1)$", "(−5; −3) не решение"))
K("G9_TB_14_241_2", r"$a = -\dfrac{1}{3}$; $a = \dfrac{1}{3}$; $a = 2$", "2 − 18a² − a = −9a³ ⇒ (a − 2)(9a² − 1) = 0 (было 1/3; −2/3)")
K("G9_TB_21_403_2", r"$0$", "расстояние от центра (3; 2) до прямой x = 7 равно 4 > 3 — общих точек нет (было 1)", dadd=OLD(r"$1$", "неверно найдено расстояние"))
K("G9_TB_25_507", r"$\dfrac{2}{3}$ или $\dfrac{6}{19}$", "y = 4x − 5, x² = 2(y − 1) ⇒ x² − 8x + 12 = 0 ⇒ 2/3 или 6/19 (было 3/5: 9/4 ≠ 2); вариант «2/3» был частью ответа — закрыт",
  drop=[2], dadd=OLD(r"$\dfrac{3}{5}$", "не удовлетворяет условию"))
K("G9_TB_18_339_е", r"$x \neq \dfrac{1}{3}$", "9x² − 6x + 1 = (3x − 1)² > 0 ⇔ x ≠ 1/3 (было x ∈ R)")
